Here is a complete, idiomatic Terraform module implementing the specified infrastructure. It follows Terraform 1.5+ and AWS Provider 5.x best practices, with explicit environment isolation via `tfvars` and workspace support.

### 📁 Module Structure
```
modules/app-infra/
├── main.tf
├── variables.tf
├── outputs.tf
├── dev.tfvars
└── prod.tfvars
```

---

### 📄 `main.tf`
```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

data "aws_caller_identity" "current" {}

# ──────────────────────────────────────────────
# S3 Bucket (Application Assets)
# ──────────────────────────────────────────────
resource "aws_s3_bucket" "app_assets" {
  bucket = var.bucket_name
  tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_s3_bucket_versioning" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Conditional Cross-Region Replication (Prod only)
resource "aws_s3_bucket_replication_configuration" "app_assets" {
  count  = var.enable_cross_region_replication ? 1 : 0
  bucket = aws_s3_bucket.app_assets.id
  role   = var.replication_role_arn

  rule {
    id     = "cross-region-replication"
    status = "Enabled"

    destination {
      bucket = var.replication_target_bucket_arn
    }
  }
}

# ──────────────────────────────────────────────
# RDS PostgreSQL Instance
# ──────────────────────────────────────────────
resource "aws_db_subnet_group" "app" {
  name       = "${var.environment}-app-db-subnet"
  subnet_ids = var.subnet_ids
  tags = {
    Environment = var.environment
  }
}

resource "aws_db_instance" "app" {
  identifier              = "${var.environment}-app-db"
  engine                  = "postgres"
  engine_version          = "15.4"
  instance_class          = var.db_instance_class
  allocated_storage       = 20
  username                = var.db_username
  password                = var.db_password
  skip_final_snapshot     = false
  backup_retention_period = var.db_backup_retention
  delete_protection       = true
  publicly_accessible     = false
  multi_az                = var.db_multi_az
  storage_encrypted       = true
  kms_key_id              = var.environment == "prod" ? var.prod_kms_key_arn : null

  db_subnet_group_name = aws_db_subnet_group.app.name

  tags = {
    Environment = var.environment
  }
}

# ─────────
